import csv,pathlib
rows=[r for r in csv.DictReader(open('A1/in/part-6.tsv'),delimiter='\t') if r['kind']=='stored' and r['machine']=='debian-desktop']
out=pathlib.Path('A1/c1/part-6.1.tsv')
header=['id','decision','sentences','what_it_does','basis','reason']
seen=set()
if out.exists():seen={r['id'] for r in csv.DictReader(out.open(),delimiter='\t')}
f=out.open('a');w=csv.writer(f,delimiter='\t',lineterminator='\n')
if not out.stat().st_size:w.writerow(header);f.flush()
def add(i,d,s,what,basis,why):
 assert len(what.split())<=15,(i,what)
 assert len(why.split())<=30,(i,why)
 if rows[i]['id'] not in seen:
  w.writerow([rows[i]['id'],d,s,what,basis,why]);f.flush();seen.add(rows[i]['id'])
def u(i,what,why):add(i,'UNKNOWN','S3-1,S3-2',what,'evidence',why)
def doc(i,d,s,what,url,why):add(i,d,s,what,'doc:'+url,why)
